<template>
  <section class="mx-auto max-w-3xl space-y-6"><header><NuxtLink to="/admin/certifications" class="text-sm font-semibold text-[var(--accent-hover)] hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--border-focus)]">← Back to certifications</NuxtLink><div class="mt-3 flex flex-wrap items-center justify-between gap-3"><h1 class="text-3xl font-bold">{{ isNew ? 'Add certification' : 'Edit certification' }}</h1><span v-if="isDirty" class="text-sm font-semibold text-[var(--accent-hover)]">Unsaved changes</span></div></header>
    <div v-if="loadPending" class="space-y-4" aria-busy="true" aria-label="Loading certification"><div v-for="n in 5" :key="n" class="h-12 animate-pulse rounded-md bg-[var(--background-muted)]" /></div><div v-else-if="loadError" class="rounded-lg border border-red-700/30 bg-[var(--background-card)] p-6" role="alert"><h2 class="font-semibold">Certification could not be loaded</h2><NuxtLink to="/admin/certifications" class="mt-4 inline-flex min-h-11 items-center rounded-md border border-[var(--border-subtle)] px-4 text-sm font-semibold focus-visible:ring-2 focus-visible:ring-[var(--border-focus)]">Back to certifications</NuxtLink></div>
    <form v-else class="space-y-6 rounded-lg border border-[var(--border-subtle)] bg-[var(--background-card)] p-4 shadow-[var(--shadow-sm)] sm:p-6" novalidate @submit.prevent="save"><div class="grid gap-5 sm:grid-cols-2"><div class="sm:col-span-2"><label for="name" class="mb-2 block text-sm font-semibold">Certification name</label><input id="name" v-model="form.name" name="name" autocomplete="off" maxlength="200" :aria-invalid="Boolean(errors.name)" class="w-full rounded-md border border-[var(--border-subtle)] bg-[var(--background-page)] px-3 py-3 focus:border-[var(--border-focus)] focus:outline-none" /><p v-if="errors.name" class="mt-2 text-sm text-red-800" role="alert">{{ errors.name }}</p></div><div class="sm:col-span-2"><label for="issuer" class="mb-2 block text-sm font-semibold">Issuer</label><input id="issuer" v-model="form.issuer" name="issuer" autocomplete="organization" maxlength="200" :aria-invalid="Boolean(errors.issuer)" class="w-full rounded-md border border-[var(--border-subtle)] bg-[var(--background-page)] px-3 py-3 focus:border-[var(--border-focus)] focus:outline-none" /><p v-if="errors.issuer" class="mt-2 text-sm text-red-800" role="alert">{{ errors.issuer }}</p></div><div><label for="issued-date" class="mb-2 block text-sm font-semibold">Issued date <span class="font-normal text-[var(--foreground-muted)]">(optional)</span></label><input id="issued-date" v-model="form.issued_date" name="issued_date" type="date" class="w-full rounded-md border border-[var(--border-subtle)] bg-[var(--background-page)] px-3 py-3 focus:border-[var(--border-focus)] focus:outline-none" /><p v-if="errors.issued_date" class="mt-2 text-sm text-red-800" role="alert">{{ errors.issued_date }}</p></div><div><label for="sort-order" class="mb-2 block text-sm font-semibold">Sort order</label><input id="sort-order" v-model.number="form.sort_order" name="sort_order" type="number" min="0" max="100000" inputmode="numeric" class="w-full rounded-md border border-[var(--border-subtle)] bg-[var(--background-page)] px-3 py-3 focus:border-[var(--border-focus)] focus:outline-none" /></div><div class="sm:col-span-2"><label for="credential-url" class="mb-2 block text-sm font-semibold">Credential URL <span class="font-normal text-[var(--foreground-muted)]">(optional)</span></label><input id="credential-url" v-model="form.credential_url" name="credential_url" type="url" autocomplete="url" placeholder="https://example.com/credential…" :aria-invalid="Boolean(errors.credential_url)" class="w-full rounded-md border border-[var(--border-subtle)] bg-[var(--background-page)] px-3 py-3 focus:border-[var(--border-focus)] focus:outline-none" /><p v-if="errors.credential_url" class="mt-2 text-sm text-red-800" role="alert">{{ errors.credential_url }}</p></div></div><label class="flex min-h-11 items-center gap-3 border-t border-[var(--border-subtle)] pt-5 text-sm font-semibold"><input v-model="form.is_published" name="is_published" type="checkbox" class="h-5 w-5 rounded border-[var(--border-subtle)] text-[var(--accent-primary)] focus:ring-2 focus:ring-[var(--border-focus)]" /> Publish on portfolio</label><div v-if="formError" class="rounded-md border border-red-700/30 bg-red-50 px-4 py-3 text-sm text-red-900" role="alert">{{ formError }}</div><div v-if="successMessage" class="rounded-md border border-emerald-700/30 bg-emerald-50 px-4 py-3 text-sm text-emerald-900" role="status" aria-live="polite">{{ successMessage }}</div><div class="flex flex-col-reverse gap-3 sm:flex-row"><button type="submit" class="min-h-11 rounded-md bg-[var(--accent-primary)] px-5 text-sm font-semibold text-white hover:bg-[var(--accent-hover)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--border-focus)] disabled:opacity-60" :disabled="saving" :aria-busy="saving">{{ saving ? 'Saving…' : 'Save certification' }}</button><NuxtLink to="/admin/certifications" class="inline-flex min-h-11 items-center justify-center rounded-md border border-[var(--border-subtle)] px-5 text-sm font-semibold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--border-focus)]">Cancel</NuxtLink></div></form>
  </section>
</template>
<script setup lang="ts">
import { z } from 'zod'
definePageMeta({ layout: 'admin', middleware: ['auth'] })
const route = useRoute(); const id = computed(() => String(route.params.id)); const isNew = computed(() => id.value === 'new')
const schema = z.object({ name: z.string().trim().min(1, 'Certification name is required.').max(200), issuer: z.string().trim().min(1, 'Issuer is required.').max(200), issued_date: z.string().date().nullable(), credential_url: z.string().trim().refine((value) => !value || /^https?:\/\//i.test(value), 'Credential URL must use HTTP or HTTPS.'), sort_order: z.number().int().min(0).max(100000), is_published: z.boolean() }).strict()
type Form = z.infer<typeof schema>; interface Response extends Form { id: string }
const form = ref<Form>({ name: '', issuer: '', issued_date: null, credential_url: '', sort_order: 0, is_published: true }); const loadPending = ref(!isNew.value); const loadError = ref<unknown>(null); const saving = ref(false); const formError = ref(''); const successMessage = ref(''); const errors = ref<Record<string, string>>({}); const initialSnapshot = ref(''); const ignoreLeavePrompt = ref(false)
if (!isNew.value) { const { data, pending, error } = await useFetch<Response>(`/api/admin/certifications/${id.value}`); loadPending.value = pending.value; loadError.value = error.value; if (data.value) form.value = { name: data.value.name, issuer: data.value.issuer, issued_date: data.value.issued_date, credential_url: data.value.credential_url ?? '', sort_order: data.value.sort_order, is_published: data.value.is_published } }
initialSnapshot.value = JSON.stringify(form.value); const isDirty = computed(() => JSON.stringify(form.value) !== initialSnapshot.value)
const validate = () => { errors.value = {}; const result = schema.safeParse({ ...form.value, issued_date: form.value.issued_date || null }); if (result.success) { form.value = result.data; return true } for (const issue of result.error.issues) { const key = String(issue.path[0] ?? 'form'); if (!errors.value[key]) errors.value[key] = issue.message } nextTick(() => document.getElementById(errors.value.name ? 'name' : errors.value.issuer ? 'issuer' : errors.value.issued_date ? 'issued-date' : 'credential-url')?.focus()); return false }
const save = async () => { if (!validate()) { formError.value = 'Review the highlighted fields before saving.'; return } saving.value = true; formError.value = ''; successMessage.value = ''; try { const response = await $fetch<Response>(isNew.value ? '/api/admin/certifications' : `/api/admin/certifications/${id.value}`, { method: isNew.value ? 'POST' : 'PUT', body: { ...form.value, issued_date: form.value.issued_date || null, credential_url: form.value.credential_url || null } }); form.value = { name: response.name, issuer: response.issuer, issued_date: response.issued_date, credential_url: response.credential_url ?? '', sort_order: response.sort_order, is_published: response.is_published }; initialSnapshot.value = JSON.stringify(form.value); ignoreLeavePrompt.value = true; successMessage.value = 'Certification saved.'; if (isNew.value) await navigateTo(`/admin/certifications/${response.id}`, { replace: true }) } catch (error) { formError.value = error instanceof Error ? error.message : 'Unable to save this certification. Try again.' } finally { saving.value = false } }
onBeforeRouteLeave(() => { if (ignoreLeavePrompt.value || !isDirty.value || saving.value || !import.meta.client) return true; return window.confirm('You have unsaved changes. Leave without saving?') }); if (import.meta.client) { const warn = (event: BeforeUnloadEvent) => { if (!isDirty.value || saving.value) return; event.preventDefault(); event.returnValue = '' }; onMounted(() => window.addEventListener('beforeunload', warn)); onBeforeUnmount(() => window.removeEventListener('beforeunload', warn)) }
</script>
